package platform

import "runtime"

// Capability reports the current platform's native capability when
// supported, falling back to a generic "stub" capability for platforms
// that have no native implementation.
func Capability() string {
	switch runtime.GOOS {
	case "linux", "darwin", "freebsd", "openbsd", "netbsd", "dragonfly", "solaris", "aix":
		return NativeCapability
	default:
		return "stub"
	}
}
